-- Hyprland config (Lua, Hyprland 0.53+). Linked to ~/.config/hypr by install.sh.
-- Split into modules next to this file:
--   binds.lua   generated by keys/build.py from keys/keymap.toml (don't edit; edit the keymap)
--   colors.lua  generated by theme/build.py from theme/gruver16.yaml (don't edit)
--   kde.lua     KDE app integration
-- Check without logging in:  Hyprland --verify-config -c ~/.config/hypr/hyprland.lua

local c = require("colors")
local rgb = function(hex, alpha) return "rgba(" .. hex .. (alpha or "ff") .. ")" end

----------------------
---- PROGRAMS --------
----------------------

local programs = {
    terminal     = "ghostty",
    -- Cmd+Space. Vicinae until the Quickshell launcher is ready, then swap these two.
    launcher     = "vicinae toggle",
    -- Cmd+Opt+Space: the other launcher.
    launcher_alt = "hyprctl notify 1 3000 0 'Quickshell launcher not built yet'",
}

------------------
---- MONITORS ----
------------------

hl.monitor({ output = "", mode = "preferred", position = "auto", scale = "auto" })

-------------------
---- AUTOSTART ----
-------------------

hl.on("hyprland.start", function()
    -- Let systemd user services see this session (Toshy runs as one), then restart Toshy so it
    -- detects Hyprland instead of whatever it saw when it started at login.
    -- (Toshy refuses to start without XDG_SESSION_TYPE.)
    hl.exec_cmd("dbus-update-activation-environment --systemd XDG_SESSION_TYPE XDG_SESSION_DESKTOP "
        .. "XDG_CURRENT_DESKTOP WAYLAND_DISPLAY DISPLAY HYPRLAND_INSTANCE_SIGNATURE "
        .. "QT_QPA_PLATFORMTHEME XDG_MENU_PREFIX "
        .. "&& systemctl --user restart toshy-config.service")
    -- Hyprland-only Ghostty look (see the end of ghostty/config.ghostty).
    hl.exec_cmd("ln -sfn hyprland.ghostty ~/.config/ghostty/session.ghostty")
    hl.exec_cmd("vicinae server")
    hl.exec_cmd("qs") -- Quickshell: bar (quickshell/ in dotfiles)
end)

require("kde")

-----------------------
---- LOOK AND FEEL ----
-----------------------

hl.config({
    general = {
        gaps_in     = 4,
        gaps_out    = 8,
        border_size = 2,
        col = {
            active_border   = rgb(c.base0D),
            inactive_border = rgb(c.base03),
        },
        resize_on_border = true,
        layout = "dwindle",
    },
    decoration = {
        rounding = 8,
        shadow = { enabled = true, range = 8, render_power = 3, color = rgb("000000", "88") },
        blur   = { enabled = true, size = 3, passes = 1 },
    },
    animations = { enabled = true },
    dwindle = { preserve_split = true },
    misc = {
        force_default_wallpaper = 0,     -- no anime mascot wallpapers
        disable_hyprland_logo   = true,
        background_color        = rgb(c.base00), -- shown where there's no wallpaper
    },
})

---------------
---- INPUT ----
---------------

hl.config({
    input = {
        -- Same layouts as KDE: US and Swedish (swerty). Opt+Space switches (see keys/keymap.toml).
        kb_layout  = "us,se",
        kb_variant = ",swerty",
        follow_mouse = 1,
        sensitivity  = 0,
    },
})

---------------------
---- KEYBINDINGS ----
---------------------

-- Everything keyboard-related lives in keys/keymap.toml -> binds.lua.
require("binds")(programs)

-- Mouse: Opt + left-drag moves a window, Opt + right-drag resizes it.
hl.bind("ALT + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind("ALT + mouse:273", hl.dsp.window.resize(), { mouse = true })

-- Media keys
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("wpctl set-volume -l 1 @DEFAULT_AUDIO_SINK@ 5%+"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),      { locked = true, repeating = true })
hl.bind("XF86AudioMute",        hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),     { locked = true })
hl.bind("XF86AudioPlay",        hl.dsp.exec_cmd("playerctl play-pause"),                            { locked = true })
hl.bind("XF86AudioNext",        hl.dsp.exec_cmd("playerctl next"),                                  { locked = true })
hl.bind("XF86AudioPrev",        hl.dsp.exec_cmd("playerctl previous"),                              { locked = true })

-----------------
---- WINDOWS ----
-----------------

hl.window_rule({
    -- Ignore maximize requests from apps; tiling decides sizes.
    name  = "suppress-maximize-events",
    match = { class = ".*" },
    suppress_event = "maximize",
})

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = { class = "^$", title = "^$", xwayland = true, float = true, fullscreen = false, pin = false },
    no_focus = true,
})

----------------
---- LAYERS ----
----------------

hl.layer_rule({
    -- Quickshell bar is translucent; blur the painting behind it (frosted wall label).
    name  = "blur-quickshell-bar",
    match = { namespace = "^quickshell-bar$" },
    blur  = true,
})

hl.layer_rule({
    -- Opt+? cheat sheet: blur the desktop behind it.
    name  = "blur-quickshell-keybinds",
    match = { namespace = "^quickshell-keybinds$" },
    blur  = true,
})
